// RequirementDetail.jsx
import React from 'react';
import './RequirementDetail.css';

// ------------------------------------------------------------
// Status vocabulary — keeps the same status values used on the
// ledger ('on schedule' / 'action window' / 'past due') but gives
// them the instrument-panel reading shown on the gauge label.
// ------------------------------------------------------------
const STATUS_READING = {
  'on schedule': 'PASSIVE',
  'action window': 'ACTIVE WINDOW',
  'past due': 'PAST DUE',
};

const getStatusColor = (status) => {
  if (status === 'past due') return '#A23E2A';
  if (status === 'action window') return '#C98A1E';
  return '#3F6B52';
};

// Cadence copy per category — swap for real regulation text when available.
const CADENCE_BY_CATEGORY = {
  'Admin & Licensing': 'Filed per Railroad Commission renewal cycle.',
  'Manuals & OQ': 'Reviewed annually under the operator OQ program.',
  'Corrosion Control': 'Tested per the CP monitoring interval.',
  'Patrolling & Odorization': 'Surveyed per class-location patrol frequency.',
  'Equipment & Valves': 'Inspected per station maintenance interval.',
  'Public Awareness': 'Distributed per the API RP 1162 program cycle.',
};

const formatDate = (isoDate) => {
  const d = new Date(`${isoDate}T00:00:00`);
  return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
};

// Best-effort "last completed" — one cycle back from the next due date.
// Replace with a real completion date field once your data model has one.
const estimateLastCompleted = (isoDate) => {
  const d = new Date(`${isoDate}T00:00:00`);
  d.setFullYear(d.getFullYear() - 1);
  return d.toISOString().slice(0, 10);
};

// ------------------------------------------------------------
// Large instrument gauge — same dial logic as the ledger's Dial,
// scaled up and paired with a printed reading underneath.
// ------------------------------------------------------------
const StatusGauge = ({ status }) => {
  const color = getStatusColor(status);
  let angle = -60;
  if (status === 'action window') angle = 0;
  if (status === 'past due') angle = 60;

  const size = 64;
  const strokeWidth = size * 0.1;
  const radius = size * 0.38;
  const center = size / 2;
  const startAngle = -120;
  const sweep = 240;
  const needleAngle = startAngle + (sweep * (angle + 60) / 120);
  const rad = (needleAngle * Math.PI) / 180;
  const needleLength = radius * 0.82;
  const nx = center + needleLength * Math.cos(rad);
  const ny = center + needleLength * Math.sin(rad);

  const arc = (from, to) => {
    const p1 = [center + radius * Math.cos((from * Math.PI) / 180), center + radius * Math.sin((from * Math.PI) / 180)];
    const p2 = [center + radius * Math.cos((to * Math.PI) / 180), center + radius * Math.sin((to * Math.PI) / 180)];
    return `M ${p1[0]} ${p1[1]} A ${radius} ${radius} 0 0 1 ${p2[0]} ${p2[1]}`;
  };

  return (
    <div className="req-gauge-panel">
      <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} className="req-gauge-svg">
        <circle cx={center} cy={center} r={radius} fill="none" stroke="#d0d9d4" strokeWidth={strokeWidth * 0.55} />
        <path d={arc(-120, -60)} fill="none" stroke="#3F6B52" strokeWidth={strokeWidth * 0.45} opacity="0.55" />
        <path d={arc(-20, 20)} fill="none" stroke="#C98A1E" strokeWidth={strokeWidth * 0.45} opacity="0.55" />
        <path d={arc(60, 120)} fill="none" stroke="#A23E2A" strokeWidth={strokeWidth * 0.45} opacity="0.55" />
        <line x1={center} y1={center} x2={nx} y2={ny} stroke={color} strokeWidth={strokeWidth * 0.8} strokeLinecap="round" />
        <circle cx={center} cy={center} r={strokeWidth * 0.7} fill="#14191C" />
      </svg>
      <span className="req-gauge-label" style={{ color }}>{STATUS_READING[status] || status}</span>
    </div>
  );
};

// ------------------------------------------------------------
// Main detail page — renders inside the existing .main-content
// wrapper in place of the route spine + ledger, sidebar untouched.
// ------------------------------------------------------------
const RequirementDetail = ({ requirement, onBack, onMarkComplete, onDispatchVendor }) => {
  if (!requirement) return null;

  const { category, citation, description, due, status, assigned } = requirement;
  const cadence = CADENCE_BY_CATEGORY[category] || 'Per applicable PHMSA / TRRC schedule.';
  const lastCompleted = estimateLastCompleted(due);

  return (
    <div className="req-detail-page">
      <div className="req-topbar">
        <div className="req-topbar-main">
          <button className="req-back-link" onClick={onBack}>
            <i className="fas fa-arrow-left"></i>
            <span>BACK TO LEDGER</span>
          </button>

          <div className="req-badge-row">
            <span className="req-citation-badge">{citation}</span>
            <span className="req-category-eyebrow">{category.toUpperCase()}</span>
          </div>

          <h1 className="req-title">{description}</h1>
        </div>

        <StatusGauge status={status} />
      </div>

      <div className="req-content-grid">
        <div className="req-col req-col-main">
          <section className="req-panel">
            <h2 className="req-panel-title">Regulation Rule</h2>
            <p className="req-rule-text">{cadence}</p>
            <div className="req-divider"></div>
            <a className="req-link-row" href="#" onClick={(e) => e.preventDefault()}>
              <i className="fas fa-external-link-alt"></i>
              <span>Read Full Regulation Text</span>
            </a>
          </section>

          <section className="req-panel">
            <h2 className="req-panel-title">Action Panel</h2>
            <div className="req-action-buttons">
              <button className="req-btn-primary" onClick={onMarkComplete}>
                <i className="fas fa-check-circle"></i>
                <span>MARK COMPLETE</span>
              </button>
              <button className="req-btn-secondary" onClick={onDispatchVendor}>
                <span>DISPATCH VENDOR</span>
              </button>
            </div>
          </section>
        </div>

        <div className="req-col req-col-side">
          <section className="req-panel">
            <h2 className="req-panel-title">Timeline</h2>
            <div className="req-timeline-row">
              <i className="fas fa-calendar-alt req-timeline-icon"></i>
              <div>
                <div className="req-timeline-label">Next Due</div>
                <div className="req-timeline-value">{formatDate(due)}</div>
              </div>
            </div>
            <div className="req-timeline-row">
              <i className="fas fa-calendar-check req-timeline-icon"></i>
              <div>
                <div className="req-timeline-label">Last Completed</div>
                <div className="req-timeline-value">{formatDate(lastCompleted)}</div>
              </div>
            </div>
          </section>

          <section className="req-panel">
            <h2 className="req-panel-title">Assignment</h2>
            <div className="req-assignment-row">
              <div className="req-avatar"><i className="fas fa-user"></i></div>
              <div>
                <div className="req-timeline-label">Current Owner</div>
                <div className="req-timeline-value">{assigned || 'Unassigned'}</div>
              </div>
            </div>
          </section>
        </div>
      </div>
    </div>
  );
};

export default RequirementDetail;
